import{_ as e,o as s,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"谷风","description":"","frontmatter":{"title":"谷风","date":"2026-11-07T00:00:00.000Z","seq":35,"categories":["美文","诗经"],"collection":"《诗经 · 国风》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·国风/谷风.md","filePath":"blogs/诗经·国风/谷风.md"}'),p={name:"blogs/诗经·国风/谷风.md"};function r(c,a,l,n,_,i){return s(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="谷风" tabindex="-1">谷风 <a class="header-anchor" href="#谷风" aria-label="Permalink to &quot;谷风&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　邶风</p><div class="poem"><p class="poem-stanza">习习谷风，以阴以雨。黾勉同心，不宜有怒。采葑采菲，无以下体？德音莫违，及尔同死。</p><p class="poem-stanza">行道迟迟，中心有违。不远伊迩，薄送我畿。谁谓荼苦，其甘如荠。宴尔新婚，如兄如弟。</p><p class="poem-stanza">泾以渭浊，湜湜其沚。宴尔新婚，不我屑以。毋逝我梁，毋发我笱。我躬不阅，遑恤我后。</p><p class="poem-stanza">就其深矣，方之舟之。就其浅矣，泳之游之。何有何亡，黾勉求之。凡民有丧，匍匐救之。</p><p class="poem-stanza">不我能畜，反以我为仇。既阻我德，贾用不售。昔育恐育鞫，及尔颠覆。既生既育，比予于毒。</p><p class="poem-stanza">我有旨蓄，亦以御冬。宴尔新婚，以我御穷。有洸有溃，既诒我肄。不念昔者，伊余来塈。</p></div>',3)])])}const u=e(p,[["render",r]]);export{d as __pageData,u as default};
